/// <summary>
/// DebuC 16.02.24
/// </summary>
class NDXMasterAllianceStructure
{
    Map masterAllianceMap;

    AVATOSId masterAlliance;

}

Method.Source:
/// <summary>
/// DebuC 16.02.24
/// </summary>
/// <returns>NDXMasterAllianceStructure</returns>
public static NDXMasterAllianceStructure construct()
{
    NDXMasterAllianceStructure  masterAllianceStructure = new NDXMasterAllianceStructure();

    masterAllianceStructure.init();

    return masterAllianceStructure;
}

/// <summary>
/// DebuC 16.02.24
/// </summary>
public void init()
{
    masterAllianceMap = new Map(Types::String, Types::Enum);
}

/// <summary>
/// DebuC 16.02.24
/// </summary>
/// <param name = "_avaTOSId">AVATOSId</param>
/// <param name = "_masterAllianceType">NDXMasterAllianceType</param>
public void addMasterAlliance(AVATOSId _avaTOSId, NDXMasterAllianceType _masterAllianceType)
{
    if(!masterAllianceMap.exists(_avaTOSId))
    {
        masterAllianceMap.insert(_avaTOSId, _masterAllianceType);
    }
}

/// <summary>
/// DebuC 16.02.24
/// </summary>
/// <param name = "_masterAlliance">AVATOSId</param>
/// <returns>AVATOSId</returns>
public AVATOSId parmMasterAlliance(AVATOSId _masterAlliance = masterAlliance)
{
    masterAlliance = _masterAlliance;

    return masterAlliance;
}

/// <summary>
/// DebuC 16.02.24
/// </summary>
/// <returns>MapEnumerator</returns>
public MapEnumerator getMasterAllianceEnumerator()
{
    return masterAllianceMap.getEnumerator();
}
